UPDATE TB_USER
SET
    phone = #{phone},
    email = #{email}
WHERE user_id = #{userId}
  AND use_yn = 'Y'

UPDATE TB_USER
SET user_pw = #{userPw}
WHERE user_id = #{userId}
  AND use_yn = 'Y'

UPDATE TB_USER
SET last_login_date = NOW()
WHERE login_id = #{loginId}

mapper.select:
SELECT COUNT(*)
FROM TB_USER
WHERE login_id = #{loginId}
